+//! Filters applied to variable values with `{{name | filter}}`.
+
+use crate::util::strings::{collapse_whitespace, kebab_case, title_case, truncate};
+
+/// A transformation applied to a variable's value before it is written out.
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub enum Filter {
+    Upper,
+    Lower,
+    Title,
+    Kebab,
+    Squash,
+    Truncate(usize),
+}
+
+impl Filter {
+    /// Parses a filter expression such as `upper` or `truncate(20)`.
+    pub fn parse(expression: &str) -> Option<Filter> {
+        let expression = expression.trim();
+        if let Some(argument) = expression
+            .strip_prefix("truncate(")
+            .and_then(|rest| rest.strip_suffix(')'))
+        {
+            return argument.trim().parse().ok().map(Filter::Truncate);
+        }
+        match expression {
+            "upper" => Some(Filter::Upper),
+            "lower" => Some(Filter::Lower),
+            "title" => Some(Filter::Title),
+            "kebab" => Some(Filter::Kebab),
+            "squash" => Some(Filter::Squash),
+            _ => None,
+        }
+    }
+
+    pub fn apply(&self, value: &str) -> String {
+        match self {
+            Filter::Upper => value.to_uppercase(),
+            Filter::Lower => value.to_lowercase(),
+            Filter::Title => title_case(value),
+            Filter::Kebab => kebab_case(value),
+            Filter::Squash => collapse_whitespace(value),
+            Filter::Truncate(max_chars) => truncate(value, *max_chars),
+        }
+    }
+}
+
+/// Applies `filters` to `value` from left to right.
+pub fn apply_all(filters: &[Filter], value: &str) -> String {
+    filters
+        .iter()
+        .fold(value.to_string(), |current, filter| filter.apply(&current))
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn parses_filters() {
+        assert_eq!(Filter::parse("upper"), Some(Filter::Upper));
+        assert_eq!(Filter::parse(" truncate( 8 ) "), Some(Filter::Truncate(8)));
+        assert_eq!(Filter::parse("shout"), None);
+    }
+
+    #[test]
+    fn chains_filters() {
+        let filters = [Filter::Squash, Filter::Upper];
+        assert_eq!(apply_all(&filters, "a   b"), "A B");
+    }
+}

